1	#include "common.h"
2	
3	#include <cuda_bf16.h>
4	
5	constexpr int NUM_WARPS = 4;
6	constexpr int TB_SIZE = NUM_WARPS * WARP_SIZE;
7	
8	constexpr int BLOCK_M = 128;
9	constexpr int MMA_K = 16;
10	
11	template <int BLOCK_N, int BLOCK_K, bool TMAP_3D>
12	__global__
13	__launch_bounds__(TB_SIZE)
14	void matmul_v1_kernel(
15	  const __grid_constant__ CUtensorMap A_tmap,
16	  const __grid_constant__ CUtensorMap B_tmap,
17	  nv_bfloat16 *C_ptr,
18	  int M, int N, int K
19	) {
20	  const int tid = threadIdx.x;
21	  const int bid = blockIdx.x;
22	
23	  const int warp_id = tid / WARP_SIZE;
24	  const int lane_id = tid % WARP_SIZE;
25	
26	  const int grid_m = M / BLOCK_M;
27	  const int grid_n = N / BLOCK_N;
28	  const int bid_m = bid / grid_n;
29	  const int bid_n = bid % grid_n;
30	
31	  const int off_m = bid_m * BLOCK_M;
32	  const int off_n = bid_n * BLOCK_N;
33	
34	  // set up smem
35	  extern __shared__ __align__(1024) char smem[];
36	  const int A_smem = static_cast<int>(__cvta_generic_to_shared(smem));
37	  const int B_smem = A_smem + BLOCK_M * BLOCK_K * sizeof(nv_bfloat16);
38	
39	  // set up mbarrier and tmem
40	  // TODO: check if speed is slower if mbar is a variable instead of an array
41	  #pragma nv_diag_suppress static_var_with_dynamic_init
42	  __shared__ uint64_t mbars[1];
43	  __shared__ int tmem_addr[1];  // tmem address is 32-bit
44	  const int mbar_addr = static_cast<int>(__cvta_generic_to_shared(mbars));
45	
46	  if (warp_id == 0 && elect_sync()) {
47	    mbarrier_init(mbar_addr, 1);  // only 1 thread issue
48	    asm volatile("fence.mbarrier_init.release.cluster;");  // visible to async proxy
49	  }
50	  else if (warp_id == 1) {
51	    // allocate tmem for output
52	    const int addr = static_cast<int>(__cvta_generic_to_shared(tmem_addr));
53	    asm volatile("tcgen05.alloc.cta_group::1.sync.aligned.shared::cta.b32 [%0], %1;" :: "r"(addr), "r"(BLOCK_N));
54	  }
55	
56	  __syncthreads();  // visible to all threads
57	  const int taddr = tmem_addr[0];  // this will be 0
58	
59	  int phase = 0;
60	
61	  // https://docs.nvidia.com/cuda/parallel-thread-execution/#tcgen05-instruction-descriptor
62	  constexpr uint32_t i_desc = (1U << 4U)   // dtype=FP32
63	                            | (1U << 7U)   // atype=BF16
64	                            | (1U << 10U)  // btype=BF16
65	                            | ((uint32_t)BLOCK_N >> 3U << 17U)  // MMA_N
66	                            | ((uint32_t)BLOCK_M >> 4U << 24U)  // MMA_M
67	                            ;
68	
69	  const int num_iters = K / BLOCK_K;
70	  for (int iter_k = 0; iter_k < num_iters; iter_k++) {
71	    // load
72	    if (warp_id == 0 && elect_sync()) {
73	      // input layout for tcgen05.mma is contiguous blocks of (MMA_M, 8)
74	      if constexpr (TMAP_3D) {
75	        // 1 issue for each A and B
76	        const int off_k = iter_k * BLOCK_K;
77	        tma_3d_g2s(A_smem, &A_tmap, 0, off_m, off_k / 8, mbar_addr);
78	        tma_3d_g2s(B_smem, &B_tmap, 0, off_n, off_k / 8, mbar_addr);
79	      } else {
80	        // (BLOCK_K / 8) issues for each A and B.
81	        for (int k = 0; k < BLOCK_K / 8; k++) {
82	          const int off_k = iter_k * BLOCK_K + k * 8;
83	          tma_2d_g2s(A_smem + k * BLOCK_M * 16, &A_tmap, off_k, off_m, mbar_addr);
84	          tma_2d_g2s(B_smem + k * BLOCK_N * 16, &B_tmap, off_k, off_n, mbar_addr);
85	        }
86	      }
87	
88	      constexpr int cp_size = (BLOCK_M + BLOCK_N) * BLOCK_K * sizeof(nv_bfloat16);
89	      asm volatile("mbarrier.arrive.expect_tx.release.cta.shared::cta.b64 _, [%0], %1;"
90	                  :: "r"(mbar_addr), "r"(cp_size) : "memory");
91	    }
92	
93	    // wait for TMA
94	    mbarrier_wait(mbar_addr, phase);
95	    asm volatile("tcgen05.fence::after_thread_sync;");  // (why) do we need this? from DeepGEMM
96	    phase ^= 1;  // flip the phase
97	
98	    // MMA
99	    if (warp_id == 0 && elect_sync()) {
100	      // set up shared memory descriptors for A and B
101	      // https://docs.nvidia.com/cuda/parallel-thread-execution/#tcgen05-shared-memory-descriptor
102	      // to understand LBO and SBO, check out Canonical layouts
103	      // https://docs.nvidia.com/cuda/parallel-thread-execution/#tcgen05-canonical-layouts
104	      auto make_desc = [](int addr, int height) -> uint64_t {
105	        const int LBO = height * 16;
106	        const int SBO = 8 * 16;
107	        return desc_encode(addr) | (desc_encode(LBO) << 16ULL) | (desc_encode(SBO) << 32ULL) | (1ULL << 46ULL);
108	      };
109	
110	      // manually unroll 1st iteration to disable accumulation
111	      tcgen05_mma_f16(taddr, make_desc(A_smem, BLOCK_M), make_desc(B_smem, BLOCK_N), i_desc, iter_k);
112	      for (int k = 1; k < BLOCK_K / MMA_K; k++) {
113	        uint64_t a_desc = make_desc(A_smem + k * BLOCK_M * 32, BLOCK_M);
114	        uint64_t b_desc = make_desc(B_smem + k * BLOCK_N * 32, BLOCK_N);
115	        tcgen05_mma_f16(taddr, a_desc, b_desc, i_desc, 1);
116	      }
117	      asm volatile("tcgen05.commit.cta_group::1.mbarrier::arrive::one.shared::cluster.b64 [%0];"
118	                  :: "r"(mbar_addr) : "memory");
119	    }
120	
121	    // wait for MMA
122	    mbarrier_wait(mbar_addr, phase);
123	    phase ^= 1;  // flip the phase
124	  }
125	
126	  // PTX doc says we need to add this before tcgen05.ld, after tcgen05.mma
127	  asm volatile("tcgen05.fence::after_thread_sync;");
128	
129	  // load 8 columns from tmem at a time -> store 16 bytes per thread to smem
130	  // (still strided though)
131	  for (int n = 0; n < BLOCK_N / 8; n++) {
132	    // https://docs.nvidia.com/cuda/parallel-thread-execution/#tcgen05-data-path-layout-d
133	    // Layout D
134	    float tmp[8];
135	    const int addr = taddr + ((warp_id * 32) << 16) + (n * 8);
136	    asm volatile("tcgen05.ld.sync.aligned.32x32b.x8.b32 {%0, %1, %2, %3, %4, %5, %6, %7}, [%8];"
137	                : "=f"(tmp[0]), "=f"(tmp[1]), "=f"(tmp[2]), "=f"(tmp[3]),
138	                  "=f"(tmp[4]), "=f"(tmp[5]), "=f"(tmp[6]), "=f"(tmp[7])
139	                : "r"(addr));
