import torch
import numpy as np
from cuda.bindings import nvrtc, driver as cd

# Minimal tcgen05 fp16->fp32 GEMM feasibility probe.
# Single CTA, M=128, N=64, K=16 (one fp16 MMA atom: MMA_K=16).
# A: (M, K) row-major in global; B: (N, K) row-major (i.e. B is K-major as the
# MMA wants: C[m,n] = sum_k A[m,k]*B[n,k]  == A @ B^T).
# We compute C = A @ B^T and compare to torch.

SRC = r'''
#include <cuda_fp16.h>

__device__ inline uint32_t elect_one() {
  uint32_t pred = 0;
  asm volatile(
    "{\n\t.reg .pred %%px;\n\t"
    "elect.sync _|%%px, %1;\n\t"
    "@%%px mov.s32 %0, 1;\n\t}"
    : "+r"(pred) : "r"(0xFFFFFFFF));
  return pred;
}

__device__ inline uint64_t desc_encode(uint64_t x){ return (x & 0x3FFFFULL) >> 4ULL; }

// no-swizzle smem matrix descriptor, K-major "contiguous blocks of (height,8)"
__device__ inline uint64_t make_desc(int addr, int height){
  const int LBO = height * 16;   // bytes
  const int SBO = 8 * 16;        // bytes
  return desc_encode(addr) | (desc_encode(LBO) << 16ULL)
       | (desc_encode(SBO) << 32ULL) | (1ULL << 46ULL);
}

extern "C" __global__ void tcgen05_probe(const half* A, const half* B, float* C,
                                         int M, int N, int K) {
  // BLOCK_M=128, BLOCK_N=64, BLOCK_K=16, MMA_K=16 (single atom)
  const int BM = 128, BN = 64, BK = 16, MMA_K = 16;
  const int tid = threadIdx.x;
  const int warp_id = tid / 32;
  const int lane = tid % 32;

  extern __shared__ __align__(1024) char smem[];
  const int A_smem = (int)__cvta_generic_to_shared(smem);
  const int B_smem = A_smem + BM * BK * (int)sizeof(half);

  #pragma nv_diag_suppress static_var_with_dynamic_init
  __shared__ uint64_t mbar[1];
  __shared__ int tmem_addr[1];
  const int mbar_addr = (int)__cvta_generic_to_shared(mbar);

  // Stage A and B into smem in the required "contiguous (height,8)" K-major layout.
  // For a tile of (height, BK=16): element (r, k) lives at byte offset
  //   block = k / 8 ; kk = k % 8
  //   base  = block * (height*8) + r*8 + kk    (in half units)
  // i.e. contiguous 8-wide K-slabs stacked, each (height x 8).
  half* As = reinterpret_cast<half*>(smem);
  half* Bs = reinterpret_cast<half*>(smem + BM * BK * sizeof(half));
  for (int idx = tid; idx < BM * BK; idx += blockDim.x) {
    int r = idx / BK, k = idx % BK;
    int blk = k / 8, kk = k % 8;
    As[blk * (BM * 8) + r * 8 + kk] = A[r * K + k];
  }
  for (int idx = tid; idx < BN * BK; idx += blockDim.x) {
    int r = idx / BK, k = idx % BK;
    int blk = k / 8, kk = k % 8;
    Bs[blk * (BN * 8) + r * 8 + kk] = B[r * K + k];
  }
  __syncthreads();

  if (warp_id == 0 && elect_one()) {
    asm volatile("mbarrier.init.shared::cta.b64 [%0], %1;" :: "r"(mbar_addr), "r"(1));
    asm volatile("fence.mbarrier_init.release.cluster;");
  } else if (warp_id == 1) {
    const int addr = (int)__cvta_generic_to_shared(tmem_addr);
    asm volatile("tcgen05.alloc.cta_group::1.sync.aligned.shared::cta.b32 [%0], %1;"
                :: "r"(addr), "r"(BN));
  }
  __syncthreads();
  const int taddr = tmem_addr[0];
  int phase = 0;

  // fp16 inputs, fp32 accumulator: a_format=0(f16), b_format=0(f16), c_format=1(f32)
  uint32_t i_desc = (1U << 4U) | ((uint32_t)BN >> 3U << 17U) | ((uint32_t)BM >> 4U << 24U);

  if (warp_id == 0 && elect_one()) {
    asm volatile("tcgen05.fence::after_thread_sync;");
    uint64_t a_desc = make_desc(A_smem, BM);
    uint64_t b_desc = make_desc(B_smem, BN);
    asm volatile(
      "{\n\t.reg .pred p;\n\t"
      "setp.ne.b32 p, %4, 0;\n\t"
      "tcgen05.mma.cta_group::1.kind::f16 [%0], %1, %2, %3, p;\n\t}"
      :: "r"(taddr), "l"(a_desc), "l"(b_desc), "r"(i_desc), "r"(0));
    asm volatile("tcgen05.commit.cta_group::1.mbarrier::arrive::one.shared::cluster.b64 [%0];"
                :: "r"(mbar_addr) : "memory");
  }
  // wait for MMA
  {
    uint32_t ticks = 0x989680;
    asm volatile(
      "{\n\t.reg .pred P1;\n\t"
      "LAB_WAIT:\n\t"
      "mbarrier.try_wait.parity.acquire.cta.shared::cta.b64 P1, [%0], %1, %2;\n\t"
      "@P1 bra.uni DONE;\n\t"
      "bra.uni LAB_WAIT;\n\t"
      "DONE:\n\t}"
      :: "r"(mbar_addr), "r"(phase), "r"(ticks));
  }
  asm volatile("tcgen05.fence::after_thread_sync;");

  // read accumulator from TMEM. Layout D: each warp owns 32 rows (warp_id*32),
  // tcgen05.ld.32x32b.x8 -> 8 floats per thread per call; columns advance by 8.
  for (int n = 0; n < BN / 8; n++) {
    float tmp[8];
    const int addr = taddr + ((warp_id * 32) << 16) + (n * 8);
    asm volatile("tcgen05.ld.sync.aligned.32x32b.x8.b32 {%0,%1,%2,%3,%4,%5,%6,%7}, [%8];"
                : "=f"(tmp[0]),"=f"(tmp[1]),"=f"(tmp[2]),"=f"(tmp[3]),
                  "=f"(tmp[4]),"=f"(tmp[5]),"=f"(tmp[6]),"=f"(tmp[7])
                : "r"(addr));
    asm volatile("tcgen05.wait::ld.sync.aligned;");
    // this thread (warp_id, lane) holds C[warp_id*32 + lane, n*8 + 0..7]
    int row = warp_id * 32 + lane;
    #pragma unroll
    for (int i = 0; i < 8; i++) C[row * N + (n * 8 + i)] = tmp[i];
  }
  __syncthreads();
  if (warp_id == 0 && elect_one())
    asm volatile("tcgen05.dealloc.cta_group::1.sync.aligned.b32 %0, %1;" :: "r"(taddr), "r"(BN));
}
'''

def ck(err):
    if isinstance(err, nvrtc.nvrtcResult):
        assert err == nvrtc.nvrtcResult.NVRTC_SUCCESS, err
    elif isinstance(err, cd.CUresult):
        assert err == cd.CUresult.CUDA_SUCCESS, err

torch.cuda.init()
_ = torch.zeros(1, device="cuda"); torch.cuda.synchronize()
err, prog = nvrtc.nvrtcCreateProgram(SRC.encode(), b"probe.cu", 0, [], []); ck(err)
opts = [b"--gpu-architecture=sm_100a", b"--std=c++17"]
(err,) = nvrtc.nvrtcCompileProgram(prog, len(opts), opts)
_, logsize = nvrtc.nvrtcGetProgramLogSize(prog)
if logsize > 1:
    log = bytearray(logsize); nvrtc.nvrtcGetProgramLog(prog, log)
    print("[NVRTC log]", log.decode(errors="replace").strip())
ck(err)
err, sz = nvrtc.nvrtcGetCUBINSize(prog); ck(err)
cubin = bytearray(sz); (err,) = nvrtc.nvrtcGetCUBIN(prog, cubin); ck(err)
err, mod = cd.cuModuleLoadData(bytes(cubin)); ck(err)
err, fn = cd.cuModuleGetFunction(mod, b"tcgen05_probe"); ck(err)
err, dev = cd.cuCtxGetDevice(); ck(err)
err, max_smem = cd.cuDeviceGetAttribute(
    cd.CUdevice_attribute.CU_DEVICE_ATTRIBUTE_MAX_SHARED_MEMORY_PER_BLOCK_OPTIN, dev); ck(err)
err, = cd.cuFuncSetAttribute(fn,
    cd.CUfunction_attribute.CU_FUNC_ATTRIBUTE_MAX_DYNAMIC_SHARED_SIZE_BYTES, max_smem); ck(err)

M, N, K = 128, 64, 16
torch.manual_seed(0)
A = torch.randn(M, K, device="cuda", dtype=torch.float16)
B = torch.randn(N, K, device="cuda", dtype=torch.float16)
C = torch.zeros(M, N, device="cuda", dtype=torch.float32)
ref = (A.float() @ B.float().T)

smem = (M * K + N * K) * 2 + 4096
cur = torch.cuda.current_stream()
