# Probe: W = V^T @ A via tcgen05, with a K-loop over pheight (K=16 per atom).
# Vt: (BLK=32, P) row-major (== Vbuf[b], already V^T). A: (P, NC) row-major.
# W[i,c] = sum_r Vt[i,r]*A[r,c]. M=32(pad 64), N=NC, K=P (loop P/16 atoms).
# Layout: stage Vt as Aop (M=BLK,K=P) and A^T as Bop (N=NC,K=P) into smem in
# the "contiguous (height,8)" K-major form, convert f32->f16.

SRC = r'''
typedef unsigned int uint32_t;
typedef unsigned long long uint64_t;
typedef unsigned short ushort;
__device__ __forceinline__ ushort f2h(float x){ ushort h; asm volatile("cvt.rn.f16.f32 %0,%1;":"=h"(h):"f"(x)); return h; }
