  if (wid == 0 && _elect_one()) _mbar_init(mbar_addr, 1);
  else if (wid == 1){ int a = (int)__cvta_generic_to_shared(tcw_tmem); _tc_alloc(a, NN); }
  __syncthreads();
  const int taddr = tcw_tmem[0];
  const uint32_t idesc = _idesc_f16(BM, NN);
  const int rmax = min(BM, NC - row0);
  const int nkt = (P + BK - 1) / BK;
  for (int kt = 0; kt < nkt; kt++){
    const int k0 = kt * BK;
    const int kthis = min(BK, P - k0);
    for (int i = tid; i < BM * BK; i += blockDim.x) As[i] = 0;
    for (int i = tid; i < NN * BK; i += blockDim.x) Bs[i] = 0;
    __syncthreads();
