#   K2 tc_ytt: YTt[c,i] = sum_k WT[c,k]*Tbuf[k,i]         -> YTt (NC x BLK), M=NC,N=BLK,K=BLK
#              (YTt = WT @ T ; YTt[c,i]=YT[i,c], YT=T^T@W)
#   K3 tc_apply: delta[r,c]=sum_i Vbuf[i,r]*YTt[c,i] ; out=A-delta  M=P,N=NC,K=BLK
