__device__ __forceinline__ uint32_t e1(){ uint32_t p=0; asm volatile("{\n\t.reg .pred %%px;\n\telect.sync _|%%px,%1;\n\t@%%px mov.s32 %0,1;\n\t}":"+r"(p):"r"(0xFFFFFFFF)); return p; }
__device__ __forceinline__ uint64_t denc(uint64_t x){ return (x&0x3FFFFULL)>>4ULL; }
