// ---------------------------------------------------------------------------
// tc_trailing_ytt: YT^T = WT @ T  (the small T-coupling GEMM, also TMEM-accum).
//   YT[i,c] = sum_k T[k,i]*W[k,c]  (=T^T@W); we have WT[c,k]=W[k,c], produce
//   YTt[c,i] = sum_k WT[c,k]*T[k,i].  MMA C[c,i]=sum_k Aop[c,k]*Bop[i,k] with
//   Aop = WT (M=NC, K=BLK), Bop = T^T (N=BLK, K=BLK; Bop[i,k]=T[k,i]).
//   grid=(col_tiles, B). M=NC tiled by 128 (>=128 constraint), N=BLK=32, K=BLK=32.
// VERIFIED end-to-end (standalone): rel ~5e-4 (fp16) chained after tc_trailing_wt.
// ---------------------------------------------------------------------------
extern "C" __global__ void tc_trailing_ytt(
    const float* WT, const float* T, float* YTt,
    int B, int NC, int BLK,
    long swb, long swc,          // WT strides (matrix, col)   [row-stride = BLK]
    long stb, long stk, long stn,// T strides (matrix, k, k')
    long syb, long syc           // YTt strides (matrix, col)  [row-stride = BLK]
){
  const int BM = 128, NN = 32, K = 32;
  const int tid = threadIdx.x, wid = tid >> 5, lane = tid & 31;
  const int mt = blockIdx.x, bid = blockIdx.y;
  if (bid >= B) return;
  const int row0 = mt * BM;
  const float* Wb = WT + (long)bid * swb;
  const float* Tb = T + (long)bid * stb;
  float* Yb = YTt + (long)bid * syb;
  extern __shared__ __align__(1024) char tcy_smem[];
  ushort* As = reinterpret_cast<ushort*>(tcy_smem);
  const int Asz = BM * K;
  ushort* Bs = As + Asz;
  const int A_smem = (int)__cvta_generic_to_shared(tcy_smem);
  const int B_smem = A_smem + Asz * (int)sizeof(ushort);
  #pragma nv_diag_suppress static_var_with_dynamic_init
  __shared__ uint64_t tcy_mbar[1];
  __shared__ int tcy_tmem[1];
  const int mbar_addr = (int)__cvta_generic_to_shared(tcy_mbar);
  if (wid == 0 && _elect_one()) _mbar_init(mbar_addr, 1);
  else if (wid == 1){ int a = (int)__cvta_generic_to_shared(tcy_tmem); _tc_alloc(a, NN); }
  __syncthreads();
  const int taddr = tcy_tmem[0];
  const uint32_t idesc = _idesc_f16(BM, NN);
  const int rmax = min(BM, NC - row0);
  for (int i = tid; i < BM * K; i += blockDim.x) As[i] = 0;
  for (int i = tid; i < NN * K; i += blockDim.x) Bs[i] = 0;
  __syncthreads();
  // Aop = WT tile: element (c-row, k) = WT[row0+c, k]
  for (int i = tid; i < rmax * K; i += blockDim.x){
    int c = i / K, k = i % K, b = k >> 3, kk = k & 7;
    As[b * (BM * 8) + c * 8 + kk] = _f2h(Wb[(long)(row0 + c) * swc + k]);
  }
  // Bop = T^T : element (refl i2, k) = T[k, i2]
  for (int i = tid; i < NN * K; i += blockDim.x){
    int i2 = i / K, k = i % K, b = k >> 3, kk = k & 7;
    Bs[b * (NN * 8) + i2 * 8 + kk] = _f2h(Tb[(long)k * stk + (long)i2 * stn]);
  }
  __syncthreads();
  if (wid == 0 && _elect_one()){
    _tc_fence();
    int na = K / 16;
    for (int ka = 0; ka < na; ka++){
      uint64_t ad = _smem_desc(A_smem + ka * BM * 32, BM);
      uint64_t bd = _smem_desc(B_smem + ka * NN * 32, NN);
      _tc_mma_f16(taddr, ad, bd, idesc, ka > 0);
    }
    _tc_commit(mbar_addr);
  }
  _mbar_wait(mbar_addr, 0);
  _tc_fence();
  for (int n = 0; n < NN / 8; n++){
    float t[8];
    const int addr = taddr + ((wid * 32) << 16) + (n * 8);
    asm volatile("tcgen05.ld.sync.aligned.32x32b.x8.b32 {%0,%1,%2,%3,%4,%5,%6,%7}, [%8];"
                : "=f"(t[0]),"=f"(t[1]),"=f"(t[2]),"=f"(t[3]),
                  "=f"(t[4]),"=f"(t[5]),"=f"(t[6]),"=f"(t[7]) : "r"(addr));
    asm volatile("tcgen05.wait::ld.sync.aligned;");
    int r = wid * 32 + lane;
    if (r < rmax){
      #pragma unroll
      for (int i = 0; i < 8; i++) Yb[(long)(row0 + r) * syc + n * 8 + i] = t[i];
    }
  }
  __syncthreads();
  if (wid == 0 && _elect_one()) _tc_dealloc(taddr, NN);
}

// ---------------------------------------------------------------------------
// tc_trailing_apply: the DOMINANT apply GEMM, delta = V @ YT, then A -= delta.
//   delta[r,c] = sum_i V[r,i]*YT[i,c] = sum_i Vbuf[i,r]*YTt[c,i].  MMA C[r,c]=
//   sum_i Aop[r,i]*Bop[c,i] with Aop = V (M=P, K=BLK; Aop[r,i]=Vbuf[i,r]),
//   Bop = YTt (N=NC, K=BLK; Bop[c,i]=YTt[c,i]).  This is where M-tiling pays off:
//   M = pheight (>=128, tiled by 128), N = NC (tiled by NTILE=256), K = BLK = 32.
//   grid=(P_tiles, NC_tiles, B). Reads A_trail (or H), writes Aout = H. TMEM-accum.
// VERIFIED end-to-end (standalone, fp16): out = A - V(T^T(V^T A)) rel ~3e-4.
// ---------------------------------------------------------------------------
extern "C" __global__ void tc_trailing_apply(
    const float* A, const float* Vt, const float* YTt, float* Aout,
    int B, int NC, int P, int BLK, int j, int jb,
    long sab, long san,          // A/Aout strides (matrix, row); trailing at [j..) x [jb..)
    long svb, long svk, long svn,// Vbuf strides
    long syb, long syc           // YTt strides (matrix, col)  [row-stride = BLK]
){
  const int BM = 128, K = 32, NTILE = 256;
  const int tid = threadIdx.x, wid = tid >> 5, lane = tid & 31;
  const int mt = blockIdx.x, ct = blockIdx.y, bid = blockIdx.z;
  if (bid >= B) return;
  const int row0 = mt * BM, col0 = ct * NTILE;
  const int NN = min(NTILE, NC - col0);
  const float* Ab = A + (long)bid * sab + (long)j * san + (long)jb;
  const float* Vb = Vt + (long)bid * svb;
  const float* Yb = YTt + (long)bid * syb;
  float* Ob = Aout + (long)bid * sab + (long)j * san + (long)jb;
  extern __shared__ __align__(1024) char tca_smem[];
  ushort* As = reinterpret_cast<ushort*>(tca_smem);
  const int Asz = BM * K;
  ushort* Bs = As + Asz;
  const int A_smem = (int)__cvta_generic_to_shared(tca_smem);
  const int B_smem = A_smem + Asz * (int)sizeof(ushort);
  #pragma nv_diag_suppress static_var_with_dynamic_init
  __shared__ uint64_t tca_mbar[1];
  __shared__ int tca_tmem[1];
  const int mbar_addr = (int)__cvta_generic_to_shared(tca_mbar);
  if (wid == 0 && _elect_one()) _mbar_init(mbar_addr, 1);
  else if (wid == 1){ int a = (int)__cvta_generic_to_shared(tca_tmem); _tc_alloc(a, NTILE); }
  __syncthreads();
  const int taddr = tca_tmem[0];
  const uint32_t idesc = _idesc_f16(BM, NTILE);
  const int rmax = min(BM, P - row0);
  for (int i = tid; i < BM * K; i += blockDim.x) As[i] = 0;
  for (int i = tid; i < NTILE * K; i += blockDim.x) Bs[i] = 0;
  __syncthreads();
  // Aop = V tile (M=P rows, K=BLK): Aop[r,i] = Vbuf[i, row0+r] (panel-relative row)
  for (int x = tid; x < rmax * K; x += blockDim.x){
    int r = x / K, i = x % K, b = i >> 3, ii = i & 7;
    As[b * (BM * 8) + r * 8 + ii] = _f2h(Vb[(long)i * svk + (long)(row0 + r) * svn]);
  }
  // Bop = YTt tile (N=NN rows, K=BLK): Bop[c,i] = YTt[col0+c, i]
  for (int x = tid; x < NN * K; x += blockDim.x){
    int c = x / K, i = x % K, b = i >> 3, ii = i & 7;
    Bs[b * (NTILE * 8) + c * 8 + ii] = _f2h(Yb[(long)(col0 + c) * syc + i]);
  }
  __syncthreads();
  if (wid == 0 && _elect_one()){
    _tc_fence();
    int na = K / 16;
    for (int ka = 0; ka < na; ka++){
      uint64_t ad = _smem_desc(A_smem + ka * BM * 32, BM);
      uint64_t bd = _smem_desc(B_smem + ka * NTILE * 32, NTILE);
      _tc_mma_f16(taddr, ad, bd, idesc, ka > 0);
    }
    _tc_commit(mbar_addr);
  }
  _mbar_wait(mbar_addr, 0);
  _tc_fence();
  // read delta (P-tile rows x NTILE cols), write Aout = A - delta (only valid cols)
  for (int n = 0; n < NTILE / 8; n++){
    float t[8];
    const int addr = taddr + ((wid * 32) << 16) + (n * 8);
    asm volatile("tcgen05.ld.sync.aligned.32x32b.x8.b32 {%0,%1,%2,%3,%4,%5,%6,%7}, [%8];"
                : "=f"(t[0]),"=f"(t[1]),"=f"(t[2]),"=f"(t[3]),
                  "=f"(t[4]),"=f"(t[5]),"=f"(t[6]),"=f"(t[7]) : "r"(addr));
    asm volatile("tcgen05.wait::ld.sync.aligned;");
    int r = wid * 32 + lane;
    if (r < rmax){
      #pragma unroll
      for (int i = 0; i < 8; i++){
        int c = n * 8 + i;
        if (c < NN){
          long off = (long)(row0 + r) * san + (long)(col0 + c);
          Ob[off] = Ab[off] - t[i];
        }
      }
    }
  }
  __syncthreads();
  if (wid == 0 && _elect_one()) _tc_dealloc(taddr, NTILE);
}
